185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
188	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
189	        if (currentOwner != null) {
190	            Pet currentPet = this.clinicService.findPetById(petId);
191	            if (currentPet != null) {
192	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
193	                currentPet.setName(petFieldsDto.getName());
194	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
195	                this.clinicService.savePet(currentPet);
196	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
