203	    @Override
204	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
205	        HttpHeaders headers = new HttpHeaders();
206	        Visit visit = visitMapper.toVisit(visitFieldsDto);
207	        Pet pet = new Pet();
208	        pet.setId(petId);
209	        visit.setPet(pet);
210	        this.clinicService.saveVisit(visit);
211	        VisitDto visitDto = visitMapper.toVisitDto(visit);
212	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
