218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner != null) {
223	            Pet pet = owner.getPet(petId);
224	            if (pet != null) {
225	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    /**
232	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where LAST3 is the
233	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
234	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
235	     *
236	     * @param lastName the owner's last name
237	     * @return the assigned customer code
238	     */
239	    private String nextCustomerCode(String lastName) {
240	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
241	        int sequence = this.clinicService.findAllOwners().size() + 1;
242	        return String.format("%s-%04d", prefix, sequence);
243	    }
244	
245	    /**
246	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
247	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
248	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
249	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
250	     * string is what gets stored and returned.
251	     *
252	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
253	     *
254	     * @param telephone the raw telephone value supplied by the client
255	     * @return the normalized E.164 telephone number
256	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
257	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
258	     *                                 digits after the {@code '+'})
259	     */
260	    private static String normalizeTelephone(String telephone) {
261	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
262	        String digits;
263	        if (cleaned.startsWith("+")) {
264	            digits = cleaned.substring(1);
265	        } else {
266	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
267	            digits = "61" + national;
268	        }
269	        if (!digits.matches("[0-9]{8,15}")) {
270	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
271	                "telephone could not be normalized to a valid E.164 number");
272	        }
273	        return "+" + digits;
274	    }
275	
276	    /**
277	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
278	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
279	     *
280	     * @param telephone the stored telephone value, possibly {@code null}
281	     * @return the E.164 form, or the raw value when it cannot be normalized
282	     */
283	    private static String toComparableTelephone(String telephone) {
284	        try {
285	            return normalizeTelephone(telephone);
286	        } catch (ResponseStatusException ex) {
287	            return telephone;
288	        }
289	    }
290	
291	    /**
292	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
293	     * containing at least one dot, none of the three sections containing whitespace or an
294	     * additional {@code @}.
295	     */
296	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
297	
298	    /**
299	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
300	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
301	     * value is then stored and returned lower-cased.
302	     *
303	     * @param email the raw email value supplied by the client, possibly {@code null}
304	     * @return the lower-cased email, or {@code null} when none was supplied
305	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
306	     *                                 is not a syntactically valid address
307	     */
308	    private static String normalizeEmail(String email) {
309	        if (email == null) {
310	            return null;
311	        }
312	        if (!EMAIL_PATTERN.matcher(email).matches()) {
313	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
314	                "email must be a syntactically valid address");
315	        }
316	        return email.toLowerCase(Locale.ROOT);
317	    }
318	
319	    /**
320	     * Common street-type abbreviations expanded to their full word during address normalization.
321	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
322	     */
323	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
324	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
325	
326	    /**
327	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
328	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
329	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
330	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
331	     * address comparison (household duplicate detection and the shared household id).
332	     *
333	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
334	     *
335	     * @param address the raw address supplied by the client, possibly {@code null}
336	     * @return the normalized address
337	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
338	     *                                 after normalization (required field)
339	     */
340	    private static String normalizeAddress(String address) {
341	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
342	        if (collapsed.isEmpty()) {
343	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
344	                "address must not be blank");
345	        }
346	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
347	        StringBuilder normalized = new StringBuilder();
348	        for (int i = 0; i < tokens.length; i++) {
349	            if (i > 0) {
350	                normalized.append(' ');
351	            }
352	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
353	        }
354	        return normalized.toString();
355	    }
356	
357	    /**
358	     * Determines whether the given normalized E.164 telephone is already used by any owner other
359	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
360	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
361	     * inputs representing the same number are treated as duplicates.
362	     *
363	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
364	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
365	     * @return {@code true} if another owner already uses the telephone
366	     */
367	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
368	        for (Owner existing : this.clinicService.findAllOwners()) {
369	            if (excludeId != null && excludeId.equals(existing.getId())) {
370	                continue;
371	            }
372	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
373	                return true;
374	            }
375	        }
376	        return false;
377	    }
378	
379	}
